"""
Sistema de idiomas de la GUI, siguiendo el mismo patrón que MantPro
(ver /home/danitxu/Programacion/Mantenimiento/idiomas.py): un diccionario
plano por idioma y una función t(clave) que resuelve el texto activo,
cayendo a español si falta la clave en el idioma seleccionado.

Cómo añadir un idioma nuevo:
  1. Copia el bloque "es" entero y tradúcelo.
  2. Añade su entrada en LANGUAGES.

El cambio de idioma requiere reiniciar la aplicación (los widgets se
construyen una sola vez con el texto ya resuelto) — mismo compromiso
que ya usa MantPro para mantener el código simple.
"""

